    def __init__(self, outline: Outline, target_points: int) -> None:
        self.outline: Outline = outline
        self.target_points = target_points
        self.building_is_not_set: bool = True
        self.current_level: int | None = None
        self.current_building: str | None = None
        self.destroying_order: Iterator[str] = iter(
            self.outline.initial_outline_buildings
        )

    def _next_level(self, catapults: int) -> int:
        if self.current_level is None:
            raise ValueError("Current level cannot be none")
        return self.LEVEL_DICTIONARY[(catapults, self.current_level)]

    def plan_catapults(
        self,
        weight_max_list: list[FastWeightMaximum],
        minimum_catapults: int,
    ) -> list[tuple[FastWeightMaximum, int, str | None]]:
        planned: list[tuple[FastWeightMaximum, int, str | None]] = []
        ordered_weights = sorted(
            weight_max_list,
            key=lambda weight: weight.catapult_left,
            reverse=True,
        )
        levels = self.BIG_LEVELS if self.target_points > 8000 else self.SMALL_LEVELS

        for weight_max in ordered_weights:
            if (
                weight_max.catapult_left <= 0
                or weight_max.catapult_left < minimum_catapults
            ):
                planned.append((weight_max, 0, None))
                continue

            if self.building_is_not_set:
                try:
                    self.current_building = next(self.destroying_order)
                except StopIteration:
                    break
                self.building_is_not_set = False

                self.current_level = levels[self.current_building]

            if self.current_level is None or self.current_building is None:
                raise ValueError("Current ruin building or level is None")

            building = self.current_building
            level = self.current_level
            cats_to_destroy = self.LEVEL_INFERRED[level]
            catapults = weight_max.catapult_left

            if catapults >= cats_to_destroy:
                next_level = 0
            else:
                next_level = self.LEVEL_DICTIONARY[(catapults, level)]
            planned.append((weight_max, catapults, building))

            if next_level == 0:
                self.building_is_not_set = True
            else:
                self.current_level = next_level

        return planned

    def building(self) -> str:
        """For cats number return building name, always actual"""
        if self.current_building is None:
            raise ValueError("Building cannot be None")
        return self.current_building
